import React, { useEffect, useRef, useState } from "react";
import { useNavigate } from "react-router-dom";
import "./Ge.css";

function Generate() {
  const canvasRef = useRef();
  const containerRef = useRef();
  const [imagePaths, setImagePaths] = useState([]);
  const [isFading, setIsFading] = useState(false);
  const [effects, setEffects] = useState({
    grain: { intensity: 300, gamma: 1.4 },
    scanlines: { gap: 3, alpha: 0.15 },
    aberration: { offset: 2 },
    glitch: { lineHeight: 4, shiftAmount: 10 }
  });
  const position = useRef({ x: 0, y: 0 });
  const offset = useRef({ x: 0, y: 0 });
  const isDragging = useRef(false);
  const animationRef = useRef();
  const navigate = useNavigate();
  const [image, setImage] = useState(null);
  const [controls, setControls] = useState({
    brightness: 100,
    contrast: 100,
    saturation: 100,
    blur: 0,
    noise: 0,
    rotation: 0,
    scale: 1
  });

  useEffect(() => {
    const stored = JSON.parse(localStorage.getItem("selectedImages") || "[]");
    if (!stored.length) {
      navigate("/"); // Redirect to home if no images selected
      return;
    }
    setImagePaths(stored);
    generateImage(stored);
    return () => cancelAnimationFrame(animationRef.current);
  }, []);

  useEffect(() => {
    const savedImage = localStorage.getItem('selectedImage');
    if (savedImage) {
      const img = new Image();
      img.onload = () => {
        setImage(img);
        applyEffects(img);
      };
      img.src = savedImage;
    }
  }, []);

  const generateGrain = (ctx, width, height) => {
    const { intensity } = effects.grain;
    if (intensity <= 0) return;

    const grainData = ctx.getImageData(0, 0, width, height);
    const data = grainData.data;
    for (let i = 0; i < data.length; i += 4) {
      const noise = Math.floor(Math.random() * intensity) - intensity / 2;
      data[i] = 255 * Math.pow(Math.min(255, Math.max(0, data[i] + noise)) / 255, 1 / effects.grain.gamma);
      data[i + 1] = 255 * Math.pow(Math.min(255, Math.max(0, data[i + 1] + noise)) / 255, 1 / effects.grain.gamma);
      data[i + 2] = 255 * Math.pow(Math.min(255, Math.max(0, data[i + 2] + noise)) / 255, 1 / effects.grain.gamma);
    }
    ctx.putImageData(grainData, 0, 0);
  };

  const applyScanlines = (ctx, width, height) => {
    const { alpha } = effects.scanlines;
    if (alpha <= 0) return;

    ctx.save();
    ctx.fillStyle = `rgba(0,0,0,${alpha})`;
    for (let y = 0; y < height; y += effects.scanlines.gap) {
      ctx.fillRect(0, y, width, 1);
    }
    ctx.restore();
  };

  const applyChromaticAberration = (ctx, width, height) => {
    const { offset } = effects.aberration;
    if (offset <= 0) return;

    const imgData = ctx.getImageData(0, 0, width, height);
    const data = imgData.data;
    const copy = new Uint8ClampedArray(data);

    for (let y = 0; y < height; y++) {
      for (let x = 0; x < width; x++) {
        const i = (y * width + x) * 4;
        const redIndex = ((y * width + Math.min(width - 1, x + offset)) * 4);
        const blueIndex = ((y * width + Math.max(0, x - offset)) * 4);
        data[i] = copy[redIndex];
        data[i + 2] = copy[blueIndex + 2];
      }
    }
    ctx.putImageData(imgData, 0, 0);
  };

  const applyGlitchEffect = (ctx, width, height) => {
    const { shiftAmount } = effects.glitch;
    if (shiftAmount <= 0) return;

    for (let y = 0; y < height; y += effects.glitch.lineHeight * 4) {
      const shift = (Math.random() - 0.5) * shiftAmount;
      const imageData = ctx.getImageData(0, y, width, effects.glitch.lineHeight);
      ctx.putImageData(imageData, shift, y);
    }
  };

  const applyPixelate = (canvas, blockSize = 12) => {
    const ctx = canvas.getContext("2d");
    const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
    const data = imageData.data;

    for (let y = 0; y < canvas.height; y += blockSize) {
      for (let x = 0; x < canvas.width; x += blockSize) {
        const i = (y * canvas.width + x) * 4;
        const r = data[i];
        const g = data[i + 1];
        const b = data[i + 2];

        for (let dy = 0; dy < blockSize; dy++) {
          for (let dx = 0; dx < blockSize; dx++) {
            const ii = ((y + dy) * canvas.width + (x + dx)) * 4;
            data[ii] = r;
            data[ii + 1] = g;
            data[ii + 2] = b;
          }
        }
      }
    }

    ctx.putImageData(imageData, 0, 0);
    return canvas;
  };

  const thresholdImage = (canvas) => {
    const ctx = canvas.getContext("2d");
    const imageData = ctx.getImageData(0, 0, 1080, 1080);
    const data = imageData.data;

    for (let i = 0; i < data.length; i += 4) {
      const avg = (data[i] + data[i + 1] + data[i + 2]) / 3;
      const val = avg > 128 ? 255 : 0;
      data[i] = data[i + 1] = data[i + 2] = val;
    }

    ctx.putImageData(imageData, 0, 0);
    return canvas;
  };

  const handleArchive = () => {
    const canvas = canvasRef.current;

    // Compress the image before storing
    const compressedImageData = compressImage(canvas);
    const timestamp = new Date().toISOString();

    // Get existing archives
    const archives = JSON.parse(localStorage.getItem("archivedImages") || "[]");

    // Add new archive
    archives.push({
      imageData: compressedImageData,
      timestamp,
      effects: { ...effects }
    });

    // Keep only the last 10 images to prevent storage quota issues
    const trimmedArchives = archives.slice(-10);

    try {
      localStorage.setItem("archivedImages", JSON.stringify(trimmedArchives));
      alert("Image archived successfully!");
    } catch (error) {
      if (error.name === 'QuotaExceededError') {
        // If still getting quota error, remove oldest images until it fits
        let currentArchives = [...trimmedArchives];
        while (currentArchives.length > 0) {
          try {
            localStorage.setItem("archivedImages", JSON.stringify(currentArchives));
            alert("Image archived successfully! (Some older images were removed due to storage limits)");
            break;
          } catch (e) {
            currentArchives.shift(); // Remove the oldest image
          }
        }
      } else {
        alert("Failed to archive image. Please try again.");
      }
    }
  };

  // Function to compress image
  const compressImage = (canvas) => {
    // Create a temporary canvas for compression
    const tempCanvas = document.createElement('canvas');
    const tempCtx = tempCanvas.getContext('2d');

    // Set a smaller size for compression
    const maxSize = 800; // Maximum dimension
    let width = canvas.width;
    let height = canvas.height;

    if (width > height && width > maxSize) {
      height = Math.round((height * maxSize) / width);
      width = maxSize;
    } else if (height > maxSize) {
      width = Math.round((width * maxSize) / height);
      height = maxSize;
    }

    tempCanvas.width = width;
    tempCanvas.height = height;

    // Draw the image at the smaller size
    tempCtx.drawImage(canvas, 0, 0, width, height);

    // Convert to JPEG with quality 0.7 for better compression
    return tempCanvas.toDataURL('image/jpeg', 0.7);
  };

  const generateImage = (imagePaths) => {
    const canvas = canvasRef.current;
    const ctx = canvas.getContext("2d");
    const width = canvas.width;
    const height = canvas.height;

    ctx.clearRect(0, 0, width, height);

    // Helper function to load images
    const loadImage = (src) =>
      new Promise((resolve) => {
        const img = new Image();
        img.crossOrigin = "Anonymous";
        img.onload = () => resolve(img);
        img.src = src;
      });

    // Function to get color swatches from an image
    const getColorSwatches = async (imageUrl) => {
      return new Promise((resolve) => {
        const img = new Image();
        img.crossOrigin = "Anonymous";
        img.onload = () => {
          const tempCanvas = document.createElement('canvas');
          const tempCtx = tempCanvas.getContext('2d');
          tempCanvas.width = 100;
          tempCanvas.height = 100;
          tempCtx.drawImage(img, 0, 0, 100, 100);

          const imageData = tempCtx.getImageData(0, 0, 100, 100);
          const pixels = imageData.data;
          const colors = new Set();

          for (let i = 0; i < pixels.length; i += 4) {
            if (pixels[i + 3] > 128) {
              const color = `rgb(${pixels[i]},${pixels[i + 1]},${pixels[i + 2]})`;
              colors.add(color);
            }
          }

          resolve(Array.from(colors));
        };
        img.src = imageUrl;
      });
    };

    // Function to draw color shapes with complete coverage
    const drawColorShapes = (colors) => {
      const gridSize = 50; // Size of each grid cell
      const cols = Math.ceil(width / gridSize);
      const rows = Math.ceil(height / gridSize);

      // Create a grid of positions
      const positions = [];
      for (let y = 0; y < rows; y++) {
        for (let x = 0; x < cols; x++) {
          positions.push({ x: x * gridSize, y: y * gridSize });
        }
      }

      // Shuffle positions
      for (let i = positions.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [positions[i], positions[j]] = [positions[j], positions[i]];
      }

      // Draw shapes to fill the grid
      positions.forEach(pos => {
        const color = colors[Math.floor(Math.random() * colors.length)];

        // Create more dynamic rectangle sizes
        const isHorizontal = Math.random() > 0.5;
        const baseSize = gridSize * (1 + Math.random() * 0.5);
        const width = isHorizontal ? baseSize * (1.5 + Math.random()) : baseSize * (0.5 + Math.random() * 0.5);
        const height = isHorizontal ? baseSize * (0.5 + Math.random() * 0.5) : baseSize * (1.5 + Math.random());

        ctx.fillStyle = color;
        ctx.fillRect(pos.x, pos.y, width, height);
      });
    };

    // Function to create and overlay image pieces
    const overlayImagePieces = (img) => {
      const numPieces = 100;
      const pieces = [];

      // Define base size for pieces
      const baseSize = Math.min(width, height) / 10;

      // Generate pieces with more varied sizes
      for (let i = 0; i < numPieces; i++) {
        // More varied size distribution
        const sizeVariation = Math.random();
        let pieceWidth, pieceHeight;

        if (sizeVariation < 0.3) {
          pieceWidth = baseSize * (0.3 + Math.random() * 0.3);
          pieceHeight = baseSize * (0.3 + Math.random() * 0.3);
        } else if (sizeVariation < 0.7) {
          pieceWidth = baseSize * (0.6 + Math.random() * 0.4);
          pieceHeight = baseSize * (0.6 + Math.random() * 0.4);
        } else {
          pieceWidth = baseSize * (1.0 + Math.random() * 0.5);
          pieceHeight = baseSize * (1.0 + Math.random() * 0.5);
        }

        if (Math.random() > 0.5) {
          if (Math.random() > 0.5) {
            pieceWidth *= 1.5;
            pieceHeight *= 0.7;
          } else {
            pieceWidth *= 0.7;
            pieceHeight *= 1.5;
          }
        }

        const x = Math.random() * (width + pieceWidth) - pieceWidth/2;
        const y = Math.random() * (height + pieceHeight) - pieceHeight/2;

        pieces.push({
          x,
          y,
          width: pieceWidth,
          height: pieceHeight,
          area: pieceWidth * pieceHeight,
          centerX: x + pieceWidth/2,
          centerY: y + pieceHeight/2
        });
      }

      // Select top 5 pieces based on area and position
      const sortedPieces = [...pieces].sort((a, b) => {
        // Calculate distance from center
        const centerX = width / 2;
        const centerY = height / 2;
        const distA = Math.sqrt(Math.pow(a.centerX - centerX, 2) + Math.pow(a.centerY - centerY, 2));
        const distB = Math.sqrt(Math.pow(b.centerX - centerX, 2) + Math.pow(b.centerY - centerY, 2));

        // Combine area and distance in the sorting
        const scoreA = a.area * (1 - distA / (width + height));
        const scoreB = b.area * (1 - distB / (width + height));

        return scoreB - scoreA;
      });

      const topFivePieces = sortedPieces.slice(0, 5);

      // Draw pieces with white/red outlines
      pieces.forEach(piece => {
        ctx.save();

        // Draw outline (red for top 5, white for others)
        ctx.strokeStyle = topFivePieces.includes(piece) ? 'red' : 'white';
        ctx.lineWidth = topFivePieces.includes(piece) ? 3 : 2; // Thicker outline for top 5
        ctx.strokeRect(piece.x, piece.y, piece.width, piece.height);

        // Create clipping path
        ctx.beginPath();
        ctx.rect(piece.x, piece.y, piece.width, piece.height);
        ctx.clip();

        // Draw the image
        ctx.drawImage(img, 0, 0, width, height);

        ctx.restore();
      });

      // Draw connecting lines between top 5 pieces
      ctx.save();
      ctx.strokeStyle = 'red';
      ctx.lineWidth = 4; // Thicker connecting lines
      ctx.lineCap = 'round'; // Rounded line ends
      ctx.beginPath();

      // Draw lines between centers of top 5 pieces
      for (let i = 0; i < topFivePieces.length; i++) {
        const current = topFivePieces[i];
        const next = topFivePieces[(i + 1) % topFivePieces.length];

        ctx.moveTo(current.centerX, current.centerY);
        ctx.lineTo(next.centerX, next.centerY);
      }

      ctx.stroke();
      ctx.restore();
    };

    // Main generation process
    Promise.all(imagePaths.map(loadImage)).then(async (images) => {
      // Create a temporary canvas for the color layer
      const colorCanvas = document.createElement('canvas');
      colorCanvas.width = width;
      colorCanvas.height = height;
      const colorCtx = colorCanvas.getContext('2d');

      // Get all color swatches from selected images
      const allColors = [];
      for (const img of images) {
        const colors = await getColorSwatches(img.src);
        allColors.push(...colors);
      }

      // Draw color shapes on the temporary canvas
      drawColorShapes(allColors);

      // Apply blur to the color layer
      const tempCanvas = document.createElement('canvas');
      tempCanvas.width = width;
      tempCanvas.height = height;
      const tempCtx = tempCanvas.getContext('2d');

      // Draw the color layer to temp canvas
      tempCtx.drawImage(colorCanvas, 0, 0);

      // Apply blur using CSS filter
      tempCtx.filter = 'blur(8px)';
      tempCtx.drawImage(colorCanvas, 0, 0);

      // Draw the blurred color layer on the main canvas
      ctx.drawImage(tempCanvas, 0, 0);

      // Set up hard-light blend mode
      ctx.globalCompositeOperation = 'hard-light';

      // Overlay image pieces
      for (const img of images) {
        overlayImagePieces(img);
      }

      // Reset blend mode
      ctx.globalCompositeOperation = 'source-over';

      // Apply effects
      generateGrain(ctx, width, height);
      applyScanlines(ctx, width, height);
      applyChromaticAberration(ctx, width, height);
      applyGlitchEffect(ctx, width, height);
    });
  };

  const handleDownload = () => {
    const canvas = canvasRef.current;
    const link = document.createElement("a");
    link.download = "generated.png";
    link.href = canvas.toDataURL("image/png");
    link.click();
  };

  const handleRegenerate = () => {
    setIsFading(true);
    setTimeout(() => {
      generateImage(imagePaths);
      setIsFading(false);
    }, 300);
  };

  const handleBack = () => {
    // Clear all image-related data from localStorage
    localStorage.removeItem("generatedImage");
    localStorage.removeItem("selectedImages");

    // Clear the canvas
    const canvas = canvasRef.current;
    const ctx = canvas.getContext("2d");
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Reset the state
    setImagePaths([]);
    setIsFading(false);

    // Navigate back to the home page
    navigate("/");
  };

  const applyEffects = (img) => {
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');

    // Set canvas size
    canvas.width = img.width;
    canvas.height = img.height;

    // Clear canvas
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Apply transformations
    ctx.save();
    ctx.translate(canvas.width/2, canvas.height/2);
    ctx.rotate((controls.rotation * Math.PI) / 180);
    ctx.scale(controls.scale, controls.scale);
    ctx.translate(-canvas.width/2, -canvas.height/2);

    // Draw image
    ctx.drawImage(img, 0, 0);

    // Apply filters
    ctx.filter = `
      brightness(${controls.brightness}%)
      contrast(${controls.contrast}%)
      saturate(${controls.saturation}%)
      blur(${controls.blur}px)
    `;

    // Apply noise
    if (controls.noise > 0) {
      const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
      const data = imageData.data;
      for (let i = 0; i < data.length; i += 4) {
        const noise = (Math.random() - 0.5) * controls.noise;
        data[i] += noise;     // red
        data[i + 1] += noise; // green
        data[i + 2] += noise; // blue
      }
      ctx.putImageData(imageData, 0, 0);
    }

    ctx.restore();
  };

  const handleControlChange = (name, value) => {
    setControls(prev => ({
      ...prev,
      [name]: value
    }));
    if (image) {
      applyEffects(image);
    }
  };

  const handleReset = () => {
    setControls({
      brightness: 100,
      contrast: 100,
      saturation: 100,
      blur: 0,
      noise: 0,
      rotation: 0,
      scale: 1
    });
    if (image) {
      applyEffects(image);
    }
  };

  const handleSave = () => {
    const canvas = canvasRef.current;
    const dataUrl = canvas.toDataURL('image/png');
    localStorage.setItem('generatedImage', dataUrl);

    // Save effects for archive
    const timestamp = new Date().toISOString();
    const archiveItem = {
      image: dataUrl,
      effects: controls,
      timestamp
    };

    const archive = JSON.parse(localStorage.getItem('archive') || '[]');
    archive.push(archiveItem);
    localStorage.setItem('archive', JSON.stringify(archive));
  };

  return (
    <div className="ge-container">
      <div className="ge-title-container">
        <h1 className="ge-title">Generate</h1>
      </div>

      <div className="ge-main">
        <div className="ge-box1">
          <h1 className="ge-list" onClick={() => navigate('/archive')} style={{ cursor: 'pointer' }}>Archive</h1>
          <h1 className="ge-list" onClick={() => navigate('/about')} style={{ cursor: 'pointer' }}>About</h1>
        </div>

        <div className="ge-canvas-container">
          <canvas
            ref={canvasRef}
            width={1080}
            height={1080}
            className="ge-canvas"
            style={{
              opacity: isFading ? 0.2 : 1,
            }}
          />

          <div className="ge-control-panel">
            <div className="ge-control-group">
              <label className="ge-control-label">Brightness</label>
              <input
                type="range"
                className="ge-control-slider"
                min="0"
                max="200"
                value={controls.brightness}
                onChange={(e) => handleControlChange('brightness', parseInt(e.target.value))}
              />
              <span className="ge-control-value">{controls.brightness}%</span>
            </div>

            <div className="ge-control-group">
              <label className="ge-control-label">Contrast</label>
              <input
                type="range"
                className="ge-control-slider"
                min="0"
                max="200"
                value={controls.contrast}
                onChange={(e) => handleControlChange('contrast', parseInt(e.target.value))}
              />
              <span className="ge-control-value">{controls.contrast}%</span>
            </div>

            <div className="ge-control-group">
              <label className="ge-control-label">Saturation</label>
              <input
                type="range"
                className="ge-control-slider"
                min="0"
                max="200"
                value={controls.saturation}
                onChange={(e) => handleControlChange('saturation', parseInt(e.target.value))}
              />
              <span className="ge-control-value">{controls.saturation}%</span>
            </div>

            <div className="ge-control-group">
              <label className="ge-control-label">Blur</label>
              <input
                type="range"
                className="ge-control-slider"
                min="0"
                max="10"
                step="0.1"
                value={controls.blur}
                onChange={(e) => handleControlChange('blur', parseFloat(e.target.value))}
              />
              <span className="ge-control-value">{controls.blur}px</span>
            </div>

            <div className="ge-control-group">
              <label className="ge-control-label">Noise</label>
              <input
                type="range"
                className="ge-control-slider"
                min="0"
                max="50"
                value={controls.noise}
                onChange={(e) => handleControlChange('noise', parseInt(e.target.value))}
              />
              <span className="ge-control-value">{controls.noise}</span>
            </div>

            <div className="ge-control-group">
              <label className="ge-control-label">Rotation</label>
              <input
                type="range"
                className="ge-control-slider"
                min="-180"
                max="180"
                value={controls.rotation}
                onChange={(e) => handleControlChange('rotation', parseInt(e.target.value))}
              />
              <span className="ge-control-value">{controls.rotation}°</span>
            </div>

            <div className="ge-control-group">
              <label className="ge-control-label">Scale</label>
              <input
                type="range"
                className="ge-control-slider"
                min="0.1"
                max="2"
                step="0.1"
                value={controls.scale}
                onChange={(e) => handleControlChange('scale', parseFloat(e.target.value))}
              />
              <span className="ge-control-value">{controls.scale}x</span>
            </div>

            <div className="ge-control-buttons">
              <button className="ge-control-button" onClick={handleReset}>Reset</button>
              <button className="ge-control-button" onClick={handleSave}>Save</button>
            </div>
          </div>
        </div>
      </div>

      <div className="ge-button-container">
        <button
          onClick={handleBack}
          className="ge-button ge-button-back"
        >
          Back
        </button>
        <button
          onClick={handleArchive}
          className="ge-button ge-button-archive"
        >
          Archive
        </button>
        <button
          onClick={handleRegenerate}
          className="ge-button ge-button-regenerate"
        >
          Regenerate
        </button>
        <button
          onClick={handleDownload}
          className="ge-button ge-button-download"
        >
          Download
        </button>
      </div>
    </div>
  );
}

export default Generate;
